<div x-data="{fps:{},errors:{},newFp:'',newError:'',probing:false,probe(id,port,csrf){this.errors[id]='';fetch('/deployments/fingerprint',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:'_csrf='+encodeURIComponent(csrf)+'&server_id='+id+'&port='+port}).then(r=>r.json()).then(r=>{if(r.ok)this.fps[id]=r.fingerprint;else this.errors[id]=r.error})},probeNew(csrf){this.newError='';this.newFp='';this.probing=true;fetch('/deployments/fingerprint-host',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:'_csrf='+encodeURIComponent(csrf)+'&server_ip='+encodeURIComponent(this.$refs.newIp.value)+'&port='+encodeURIComponent(this.$refs.newPort.value)}).then(async r=>({ok:r.ok,data:await r.json()})).then(r=>{if(r.ok&&r.data.ok)this.newFp=r.data.fingerprint;else this.newError=r.data.error||'No se pudo verificar el servidor'}).catch(()=>this.newError='No se pudo conectar al servidor').finally(()=>this.probing=false)}}" class="space-y-6">
