   <div class="grid md:grid-cols-2 gap-5"><label class="grid md:grid-cols-[180px_1fr] items-center gap-3"><span>IP del servidor</span><input x-ref="newIp" required name="server_ip" class="bg-slate-800 border border-slate-700 rounded p-3" placeholder="203.0.113.10"></label><label class="grid grid-cols-[110px_1fr] items-center gap-3"><span>Puerto SSH</span><input x-ref="newPort" required type="number" min="1" max="65535" name="port" value="35222" class="bg-slate-800 border border-slate-700 rounded p-3"></label></div>
